"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[2393],{5058(e,n,a){a.r(n),a.d(n,{assets:()=>p,contentTitle:()=>c,default:()=>m,frontMatter:()=>l,metadata:()=>i,toc:()=>g});const i=JSON.parse('{"id":"part4-ml-foundations/ml-as-geometry","title":"Machine Learning as Geometry \u2022 Deep Learning with PyTorch","description":"A concrete mental model: data become points, and learning becomes fitting (or separating) shapes in space.","source":"@site/docs/part4-ml-foundations/02-ml-as-geometry.mdx","sourceDirName":"part4-ml-foundations","slug":"/part4-ml-foundations/02-ml-as-geometry","permalink":"/tutorials/part4-ml-foundations/02-ml-as-geometry","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":2,"frontMatter":{"title":"Machine Learning as Geometry \u2022 Deep Learning with PyTorch","slug":"/part4-ml-foundations/02-ml-as-geometry","description":"A concrete mental model: data become points, and learning becomes fitting (or separating) shapes in space.","sidebar_label":"2. Machine learning as geometry","pagination_label":"2. Machine learning as geometry","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"1. PyTorch foundations","permalink":"/tutorials/part4-ml-foundations/01-introduction-pytorch"},"next":{"title":"3. Linear regression","permalink":"/tutorials/part4-ml-foundations/03-linear-regression"}}');var t=a(4848),s=a(8453),r=a(8172);const o=JSON.parse('{"sourcePath":"part4-ml-foundations/02-ml-as-geometry.html","route":"/part4-ml-foundations/02-ml-as-geometry","kind":"chapter","partId":"part4","partLabel":"Part IV - Machine Learning Foundations","accent":"amber","heading":"Machine Learning as Geometry","title":"Machine Learning as Geometry \u2022 Deep Learning with PyTorch","description":"A concrete mental model: data become points, and learning becomes fitting (or separating) shapes in space.","readingMinutes":3,"bodyClass":"","normalizeMath":true,"toc":[{"id":"data-points","label":"1. Data as Points, Models as Shapes"},{"id":"regression","label":"2. Regression: Fitting Numbers"},{"id":"classification","label":"3. Classification: Separating Categories"},{"id":"supervised","label":"4. Supervised Learning in One Picture"}],"html":"<div class=\\"wrap\\">\\n      <article class=\\"card\\">\\n        <div class=\\"card__topbar\\" aria-hidden=\\"true\\"></div>\\n\\n        <header>\\n          <div class=\\"kicker\\">Chapter 2 \u2022 Geometric Foundations</div>\\n          \\n          <p class=\\"subtitle\\">\\n            A concrete mental model: data become points, and learning becomes fitting (or separating)\\n            shapes in space.\\n          </p>\\n        </header>\\n\\n        <main>\\n          <p>\\n            Most descriptions of machine learning make it sound mysterious: computers \u201clearn from\\n            experience\u201d and \u201cimprove automatically.\u201d In this book, we\u2019ll use a much simpler,\\n            concrete view:\\n          </p>\\n\\n          <blockquote>\\n            <strong>Machine learning is, at its core, a geometry problem.</strong>\\n          </blockquote>\\n\\n          <p>\\n            We turn data into points in a space, then learn shapes\u2014lines, planes, and curves\u2014that fit\\n            or separate those points.\\n          </p>\\n\\n          <hr>\\n\\n          <section class=\\"section\\" aria-labelledby=\\"data-points\\">\\n            <h2 id=\\"data-points\\">1. Data as Points, Models as Shapes</h2>\\n            <p>Every machine learning problem has two parts:</p>\\n\\n            <figure class=\\"figure\\">\\n              <img src=\\"/tutorials/images/ml-geometry-points.svg\\" alt=\\"A coordinate plane showing example data as scattered points in a feature space.\\" loading=\\"lazy\\">\\n              <figcaption>\\n                A geometric view of data: each example becomes a point in feature space.\\n              </figcaption>\\n            </figure>\\n\\n            <ol>\\n              <li>\\n                <strong>Features \u2192 points in space</strong>\\n                <ul>\\n                  <li>\\n                    A person becomes a point with coordinates like\\n                    <em>(years of experience, age, education level, \u2026)</em>.\\n                  </li>\\n                  <li>\\n                    A patient becomes a point like <em>(height, weight, blood pressure, \u2026)</em>.\\n                  </li>\\n                  <li>Each example is a point in a 2D, 3D, or higher-dimensional space.</li>\\n                </ul>\\n              </li>\\n              <li>\\n                <strong>Model \u2192 a geometric object</strong>\\n                <ul>\\n                  <li>In 2D: a <strong>line</strong> or <strong>curve</strong></li>\\n                  <li>In 3D: a <strong>plane</strong> or <strong>surface</strong></li>\\n                  <li>\\n                    In higher dimensions: a <strong>hyperplane</strong> or more complex surface\\n                  </li>\\n                </ul>\\n              </li>\\n            </ol>\\n\\n            <p>Learning means adjusting that geometric object so that it matches the data well.</p>\\n          </section>\\n\\n          <section class=\\"section\\" aria-labelledby=\\"regression\\">\\n            <h2 id=\\"regression\\">2. Regression: Fitting Numbers</h2>\\n            <p>\\n              <strong>Regression</strong> is about predicting a <strong>number</strong>: a salary, a\\n              house price, a temperature.\\n            </p>\\n\\n            <figure class=\\"figure\\">\\n              <img src=\\"/tutorials/images/ml-regression-line.svg\\" alt=\\"A scatter plot with a straight best-fit line illustrating linear regression.\\" loading=\\"lazy\\">\\n              <figcaption>\\n                Regression fits a shape (often a line) through a cloud of points.\\n              </figcaption>\\n            </figure>\\n\\n            <h3 id=\\"example-salary-vs-experience\\">Example: Salary vs Experience</h3>\\n            <p>We want to predict salary from years of experience:</p>\\n            <ul>\\n              <li>\\n                For each person, we record\\n                <ul>\\n                  <li>\\\\( x \\\\) = years of experience</li>\\n                  <li>\\\\( y \\\\) = salary</li>\\n                </ul>\\n              </li>\\n              <li>Each person is a point \\\\((x, y)\\\\) on a 2D graph.</li>\\n            </ul>\\n\\n            <p>We look for a line:</p>\\n            <p>\\\\[ y = mx + b \\\\]</p>\\n\\n            <ul>\\n              <li>\\\\( m \\\\): how much salary increases per year</li>\\n              <li>\\\\( b \\\\): salary when experience is zero</li>\\n            </ul>\\n\\n            <p>\\n              The learned \\\\( m \\\\) and \\\\( b \\\\) define our model: given a new \\\\( x \\\\), we predict\\n              \\\\( y \\\\).\\n            </p>\\n\\n            <p>\\n              With more features (experience, age, education, location), each person becomes a point\\n              in higher dimensions, and the model becomes a <strong>plane</strong> or\\n              <strong>hyperplane</strong> instead of a line. With nonlinear relationships, we replace\\n              straight lines with <strong>curves</strong> or more flexible surfaces\u2014but the geometric\\n              idea is the same: <strong>we fit a shape to a cloud of points</strong>.\\n            </p>\\n          </section>\\n\\n          <section class=\\"section\\" aria-labelledby=\\"classification\\">\\n            <h2 id=\\"classification\\">3. Classification: Separating Categories</h2>\\n            <p>\\n              <strong>Classification</strong> is about predicting a <strong>category</strong>:\\n              spam/not spam, dog/cat, fraud/not fraud, at risk/not at risk.\\n            </p>\\n\\n            <figure class=\\"figure\\">\\n              <img src=\\"/tutorials/images/ml-classification-boundary.svg\\" alt=\\"Two colored clusters of points separated by a decision boundary line.\\" loading=\\"lazy\\">\\n              <figcaption>\\n                Classification learns a decision boundary that separates labeled points.\\n              </figcaption>\\n            </figure>\\n\\n            <h3 id=\\"example-cardiovascular-risk-from-height-and-weight\\">Example: Cardiovascular Risk from Height and Weight</h3>\\n            <p>We want to predict cardiovascular <strong>risk</strong> from:</p>\\n            <ul>\\n              <li>\\\\( x_1 \\\\) = height</li>\\n              <li>\\\\( x_2 \\\\) = weight</li>\\n            </ul>\\n\\n            <p>We encode the label as:</p>\\n            <ul>\\n              <li><code>0</code> = not at risk</li>\\n              <li><code>1</code> = at risk</li>\\n            </ul>\\n\\n            <p>Steps:</p>\\n            <ol>\\n              <li>Plot each patient as a point \\\\((x_1, x_2)\\\\) in 2D.</li>\\n              <li>Color points by label (e.g. blue = 0, green = 1).</li>\\n              <li>Find a <strong>line</strong> that separates the colors as well as possible.</li>\\n            </ol>\\n\\n            <p>This line is a <strong>decision boundary</strong>:</p>\\n            <ul>\\n              <li>One side \u2192 predicted \u201cnot at risk\u201d</li>\\n              <li>Other side \u2192 predicted \u201cat risk\u201d</li>\\n            </ul>\\n\\n            <p>\\n              In problems like <strong>fraud detection</strong>, each transaction is a point in a\\n              high-dimensional space. The model learns a boundary\u2014no longer a simple visible line, but\\n              still a geometric surface\u2014that separates \u201cfraud\u201d from \u201cnot fraud\u201d.\\n            </p>\\n          </section>\\n\\n          <section class=\\"section\\" aria-labelledby=\\"supervised\\">\\n            <h2 id=\\"supervised\\">4. Supervised Learning in One Picture</h2>\\n            <p>Both regression and classification are forms of <strong>supervised learning</strong>:</p>\\n            <ul>\\n              <li>We know the <strong>inputs</strong> (features).</li>\\n              <li>We know the <strong>targets</strong> (numbers or labels).</li>\\n              <li>We learn a function that maps inputs to targets from many examples.</li>\\n            </ul>\\n\\n            <p>Geometrically:</p>\\n            <ul>\\n              <li><strong>Regression</strong> \u2192 fit a line/plane/curve through points.</li>\\n              <li>\\n                <strong>Classification</strong> \u2192 find a boundary that separates differently labeled\\n                points.\\n              </li>\\n            </ul>\\n\\n            <p>\\n              As we move to deep learning and more complex architectures, the spaces and shapes become\\n              higher-dimensional and more flexible. But the fundamental picture remains:\\n            </p>\\n\\n            <blockquote>\\n              <strong>Data are points.<br>\\n              Models are shapes.<br>\\n              Learning is finding the shapes that best match the points.</strong>\\n            </blockquote>\\n          </section>\\n        </main>\\n\\n        <div class=\\"footer\\">Deep Learning with PyTorch \u2022 Concepts</div>\\n      </article>\\n    </div>"}'),l={title:"Machine Learning as Geometry \u2022 Deep Learning with PyTorch",slug:"/part4-ml-foundations/02-ml-as-geometry",description:"A concrete mental model: data become points, and learning becomes fitting (or separating) shapes in space.",sidebar_label:"2. Machine learning as geometry",pagination_label:"2. Machine learning as geometry",hide_title:!0,hide_table_of_contents:!0},c=void 0,p={},g=[];function d(e){return(0,t.jsx)(r.A,{content:o})}function m(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(d,{...e})}):d()}}}]);